CREATE TABLE public.news_sources (id text PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', kind text NOT NULL DEFAULT 'press', reputation integer NOT NULL DEFAULT 72 CHECK (reputation BETWEEN 0 AND 100), city_id text REFERENCES public.cities(id), scope text NOT NULL DEFAULT 'national' CHECK(scope IN ('local','regional','national')), logo text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')));
GRANT SELECT ON public.news_sources TO authenticated; GRANT ALL ON public.news_sources TO service_role;
ALTER TABLE public.news_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY "active fictional news sources" ON public.news_sources FOR SELECT TO authenticated USING(status='active');
CREATE TABLE public.news_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), new_hours integer NOT NULL DEFAULT 24 CHECK(new_hours>0), recent_hours integer NOT NULL DEFAULT 72 CHECK(recent_hours>0), archive_days integer NOT NULL DEFAULT 7 CHECK(archive_days>0), important_threshold integer NOT NULL DEFAULT 80 CHECK(important_threshold BETWEEN 0 AND 100), notification_cooldown_hours integer NOT NULL DEFAULT 6 CHECK(notification_cooldown_hours>=0), generation_days integer NOT NULL DEFAULT 1 CHECK(generation_days>0), page_size integer NOT NULL DEFAULT 20 CHECK(page_size BETWEEN 1 AND 100));
GRANT SELECT ON public.news_settings TO authenticated; GRANT ALL ON public.news_settings TO service_role;
ALTER TABLE public.news_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "news configuration read" ON public.news_settings FOR SELECT TO authenticated USING(true);
ALTER TABLE public.events ADD COLUMN scope text NOT NULL DEFAULT 'local' CHECK(scope IN('local','regional','national')), ADD COLUMN region text, ADD COLUMN category text NOT NULL DEFAULT 'Vie locale', ADD COLUMN importance integer NOT NULL DEFAULT 40 CHECK(importance BETWEEN 0 AND 100), ADD COLUMN status text NOT NULL DEFAULT 'scheduled' CHECK(status IN('scheduled','published','cancelled')), ADD COLUMN location_id uuid REFERENCES public.locations(id), ADD COLUMN organization_id uuid REFERENCES public.organizations(id), ADD COLUMN organization_event_id uuid REFERENCES public.organization_events(id), ADD COLUMN source_id text REFERENCES public.news_sources(id), ADD COLUMN event_key text UNIQUE, ADD COLUMN news_title text, ADD COLUMN news_summary text, ADD COLUMN news_body text, ADD COLUMN image text, ADD COLUMN target_kind text NOT NULL DEFAULT 'city' CHECK(target_kind IN('city','location','organization','participation','general'));
ALTER TABLE public.news ADD COLUMN summary text NOT NULL DEFAULT '', ADD COLUMN image text, ADD COLUMN category text NOT NULL DEFAULT 'Société', ADD COLUMN source_id text REFERENCES public.news_sources(id), ADD COLUMN author text NOT NULL DEFAULT 'La rédaction', ADD COLUMN city_id text REFERENCES public.cities(id), ADD COLUMN region text, ADD COLUMN scope text NOT NULL DEFAULT 'national' CHECK(scope IN('local','regional','national')), ADD COLUMN importance integer NOT NULL DEFAULT 40 CHECK(importance BETWEEN 0 AND 100), ADD COLUMN status text NOT NULL DEFAULT 'published' CHECK(status IN('draft','published','archived')), ADD COLUMN event_id uuid UNIQUE REFERENCES public.events(id), ADD COLUMN location_id uuid REFERENCES public.locations(id), ADD COLUMN organization_id uuid REFERENCES public.organizations(id), ADD COLUMN related_entities jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.news ALTER COLUMN published_at SET DEFAULT public.game_now();
ALTER TABLE public.events ALTER COLUMN created_at SET DEFAULT public.game_now();
ALTER POLICY "news read" ON public.news USING(status IN('published','archived') AND published_at<=public.game_now());
ALTER POLICY "events read" ON public.events USING(status='published' AND starts_at<=public.game_now());
CREATE INDEX news_publication_order ON public.news(published_at DESC,importance DESC);
CREATE TABLE public.news_reads (user_id uuid NOT NULL DEFAULT auth.uid(), news_id uuid NOT NULL REFERENCES public.news(id) ON DELETE CASCADE, read_at timestamptz NOT NULL DEFAULT public.game_now(), PRIMARY KEY(user_id,news_id));
GRANT SELECT ON public.news_reads TO authenticated; GRANT ALL ON public.news_reads TO service_role;
ALTER TABLE public.news_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "private news reading" ON public.news_reads FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.news_bookmarks (user_id uuid NOT NULL DEFAULT auth.uid(), news_id uuid NOT NULL REFERENCES public.news(id) ON DELETE CASCADE, saved_at timestamptz NOT NULL DEFAULT public.game_now(), PRIMARY KEY(user_id,news_id));
GRANT SELECT ON public.news_bookmarks TO authenticated; GRANT ALL ON public.news_bookmarks TO service_role;
ALTER TABLE public.news_bookmarks ENABLE ROW LEVEL SECURITY;
CREATE POLICY "private news bookmarks" ON public.news_bookmarks FOR SELECT TO authenticated USING(user_id=auth.uid());
ALTER TABLE public.user_settings ADD COLUMN news_personalized boolean NOT NULL DEFAULT true, ADD COLUMN news_notifications boolean NOT NULL DEFAULT true;
ALTER TABLE public.notifications ADD COLUMN news_id uuid REFERENCES public.news(id) ON DELETE CASCADE, ADD COLUMN world_at timestamptz;
CREATE UNIQUE INDEX notification_news_once ON public.notifications(user_id,news_id) WHERE news_id IS NOT NULL;
CREATE OR REPLACE FUNCTION public.notify_news(_news_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE n public.news; e public.events; threshold integer; cooldown integer;
BEGIN SELECT * INTO n FROM public.news WHERE id=_news_id AND status='published' AND published_at<=public.game_now(); IF NOT FOUND THEN RETURN; END IF;
SELECT * INTO e FROM public.events WHERE id=n.event_id;
SELECT important_threshold,notification_cooldown_hours INTO threshold,cooldown FROM public.news_settings WHERE id=1;
IF n.importance<COALESCE(threshold,80) THEN RETURN; END IF;
INSERT INTO public.notifications(user_id,title,body,news_id,world_at)
SELECT c.user_id,'Actualité importante',n.title,n.id,n.published_at FROM public.characters c LEFT JOIN public.user_settings s ON s.user_id=c.user_id
WHERE COALESCE(s.notifications_enabled,true) AND COALESCE(s.news_notifications,true)
AND ((e.target_kind='city' AND n.city_id=c.city_id)
OR (e.target_kind='location' AND (EXISTS(SELECT 1 FROM public.study_enrollments st WHERE st.character_id=c.id AND st.location_id=n.location_id) OR EXISTS(SELECT 1 FROM public.employments emp JOIN public.jobs j ON j.id=emp.job_id WHERE emp.character_id=c.id AND j.location_id=n.location_id)))
OR (e.target_kind='organization' AND EXISTS(SELECT 1 FROM public.memberships m WHERE m.character_id=c.id AND m.organization_id=n.organization_id AND m.status='active'))
OR (e.target_kind='participation' AND EXISTS(SELECT 1 FROM public.social_participations p JOIN public.activities a ON a.id=p.activity_id WHERE p.character_id=c.id AND p.event_id=e.organization_event_id AND p.status IN('reserved','running') AND a.end_time>=public.game_now())))
AND NOT EXISTS(SELECT 1 FROM public.notifications nf WHERE nf.user_id=c.user_id AND nf.news_id IS NOT NULL AND nf.news_id<>n.id AND nf.world_at>n.published_at-COALESCE(cooldown,6)*interval '1 hour')
ON CONFLICT DO NOTHING;
END $$;
REVOKE ALL ON FUNCTION public.notify_news(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.notify_news(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.publish_world_event(_event_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE e public.events; nid uuid;
BEGIN SELECT * INTO e FROM public.events WHERE id=_event_id FOR UPDATE;
IF NOT FOUND OR e.status='cancelled' OR e.starts_at IS NULL OR e.starts_at>public.game_now() THEN RETURN NULL; END IF;
IF e.source_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.news_sources WHERE id=e.source_id AND status='active') THEN RETURN NULL; END IF;
INSERT INTO public.news(title,summary,body,image,category,source_id,published_at,city_id,region,scope,importance,event_id,location_id,organization_id)
VALUES(COALESCE(e.news_title,e.title),COALESCE(e.news_summary,e.description),COALESCE(e.news_body,e.description),e.image,e.category,e.source_id,e.starts_at,e.city_id,e.region,e.scope,e.importance,e.id,e.location_id,e.organization_id)
ON CONFLICT(event_id) DO NOTHING;
SELECT id INTO nid FROM public.news WHERE event_id=e.id;
UPDATE public.events SET status='published' WHERE id=e.id AND status<>'published'; PERFORM public.notify_news(nid); RETURN nid;
END $$;
REVOKE ALL ON FUNCTION public.publish_world_event(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.publish_world_event(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.event_news_publication() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='scheduled' AND NEW.starts_at<=public.game_now() AND NEW.source_id IS NOT NULL THEN PERFORM public.publish_world_event(NEW.id); END IF; RETURN NEW; END $$;
CREATE TRIGGER world_event_to_news AFTER INSERT OR UPDATE OF starts_at,source_id,news_body ON public.events FOR EACH ROW EXECUTE FUNCTION public.event_news_publication();
CREATE OR REPLACE FUNCTION public.mark_news_read(_news_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Non connecté'; END IF; IF NOT EXISTS(SELECT 1 FROM public.news WHERE id=_news_id AND status IN('published','archived') AND published_at<=public.game_now()) THEN RAISE EXCEPTION 'Article indisponible'; END IF; INSERT INTO public.news_reads(user_id,news_id) VALUES(auth.uid(),_news_id) ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.mark_news_read(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.mark_news_read(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.bookmark_news(_news_id uuid,_saved boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Non connecté'; END IF; IF NOT EXISTS(SELECT 1 FROM public.news WHERE id=_news_id AND status IN('published','archived') AND published_at<=public.game_now()) THEN RAISE EXCEPTION 'Article indisponible'; END IF; IF _saved THEN INSERT INTO public.news_bookmarks(user_id,news_id) VALUES(auth.uid(),_news_id) ON CONFLICT DO NOTHING; ELSE DELETE FROM public.news_bookmarks WHERE user_id=auth.uid() AND news_id=_news_id; END IF; END $$;
REVOKE ALL ON FUNCTION public.bookmark_news(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.bookmark_news(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.news_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE c public.characters; region_name text; result jsonb;
BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Non connecté'; END IF; SELECT * INTO c FROM public.characters WHERE user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Personnage introuvable'; END IF; SELECT region INTO region_name FROM public.cities WHERE id=c.city_id;
SELECT jsonb_build_object('world_now',public.game_now(),'city_id',c.city_id,'region',region_name,
'preferences',jsonb_build_object('news_personalized',COALESCE((SELECT news_personalized FROM public.user_settings WHERE user_id=auth.uid()),true),'news_notifications',COALESCE((SELECT news_notifications FROM public.user_settings WHERE user_id=auth.uid()),true)),
'settings',COALESCE((SELECT to_jsonb(s) FROM public.news_settings s WHERE id=1),'{"new_hours":24,"recent_hours":72,"archive_days":7,"important_threshold":80,"page_size":20}'::jsonb),
'unread_count',(SELECT count(*) FROM public.news n WHERE status='published' AND published_at<=public.game_now() AND published_at>public.game_now()-COALESCE((SELECT archive_days FROM public.news_settings WHERE id=1),7)*interval '1 day' AND NOT EXISTS(SELECT 1 FROM public.news_reads r WHERE r.news_id=n.id AND r.user_id=auth.uid())),
'articles',COALESCE((SELECT jsonb_agg(payload ORDER BY published_at DESC) FROM (
SELECT n.published_at,to_jsonb(n)||jsonb_build_object('source',(SELECT to_jsonb(src) FROM public.news_sources src WHERE src.id=n.source_id AND src.status='active'),'city_name',(SELECT name FROM public.cities WHERE id=n.city_id),'location',(SELECT jsonb_build_object('id',l.id,'name',l.name,'city_id',l.city_id,'district_id',l.district_id) FROM public.locations l WHERE l.id=n.location_id),'organization',(SELECT jsonb_build_object('id',o.id,'name',o.name,'city_id',o.city_id) FROM public.organizations o WHERE o.id=n.organization_id AND o.status='active' AND o.visibility='public'),'event',(SELECT jsonb_build_object('id',e.id,'title',e.title,'description',e.description,'starts_at',e.starts_at,'status',e.status) FROM public.events e WHERE e.id=n.event_id AND e.status='published'),
'read_at',(SELECT r.read_at FROM public.news_reads r WHERE r.news_id=n.id AND r.user_id=auth.uid()),'bookmarked',EXISTS(SELECT 1 FROM public.news_bookmarks b WHERE b.news_id=n.id AND b.user_id=auth.uid()),
'agenda_activity_id',(SELECT a.id FROM public.activities a JOIN public.events e ON e.organization_event_id=a.organization_event_id WHERE e.id=n.event_id AND a.character_id=c.id AND a.status IN('planned','running') ORDER BY a.start_time LIMIT 1),
'relevance',(CASE WHEN n.city_id=c.city_id THEN 30 WHEN n.region=region_name THEN 15 WHEN n.scope='national' THEN 10 ELSE 0 END)+(CASE WHEN (c.path_id='student' AND n.category IN('Éducation','Vie locale')) OR (c.path_id IN('young_worker','early_career') AND n.category IN('Emploi','Économie','Transport','Technologie')) THEN 10 ELSE 0 END)+(CASE WHEN EXISTS(SELECT 1 FROM public.memberships m WHERE m.character_id=c.id AND m.organization_id=n.organization_id AND m.status='active') THEN 30 ELSE 0 END)+(CASE WHEN EXISTS(SELECT 1 FROM public.study_enrollments st WHERE st.character_id=c.id AND st.location_id=n.location_id) OR EXISTS(SELECT 1 FROM public.employments emp JOIN public.jobs j ON j.id=emp.job_id WHERE emp.character_id=c.id AND j.location_id=n.location_id) THEN 20 ELSE 0 END)) AS payload
FROM public.news n WHERE n.status IN('published','archived') AND n.published_at<=public.game_now() ORDER BY n.published_at DESC LIMIT 500) articles),'[]'::jsonb)) INTO result; RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.news_state() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.news_state() TO authenticated;
CREATE OR REPLACE FUNCTION public.refresh_world_news() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE ci public.cities; day date:=(public.game_now() AT TIME ZONE 'UTC')::date; slot integer; kind text; category_name text; headline text; summary_text text; body_text text; image_key text; lid uuid; oid uuid; oeid uuid; published_time timestamptz; importance_value integer; i integer; result_count integer:=0;
BEGIN PERFORM pg_advisory_xact_lock(505005); IF NOT EXISTS(SELECT 1 FROM public.news_sources WHERE status='active') THEN RETURN 0; END IF;
FOR i IN 0..2 LOOP
published_time:=((day-i)::timestamp+interval '6 hours') AT TIME ZONE 'UTC'; IF published_time>public.game_now() THEN CONTINUE; END IF;
FOR ci IN SELECT * FROM public.cities WHERE available ORDER BY sort_order LOOP
slot:=(extract(doy FROM day-i)::integer+ci.sort_order)%7; oid:=NULL; oeid:=NULL; image_key:=NULL;
CASE slot
WHEN 0 THEN kind:='commerce';category_name:='Économie';headline:='Un nouveau commerce ouvre ses portes à '||ci.name;summary_text:='La vie de quartier accueille une nouvelle adresse et de premiers visiteurs.';body_text:='Une nouvelle boutique accueille les habitants près du centre-ville. L’équipe présente une sélection de produits du quotidien et met l’accent sur la proximité.\n\nCette ouverture illustre le renouvellement des commerces locaux. Les habitants peuvent découvrir le lieu dans les rues de leur quartier. Aucun changement de prix ou de revenu n’est associé à cette annonce.';importance_value:=55;
WHEN 1 THEN kind:='travaux';category_name:='Vie locale';headline:='Le centre de '||ci.name||' se prépare à des travaux';summary_text:='Une opération d’entretien des espaces publics est annoncée dans le quartier central.';body_text:='Les services locaux annoncent des travaux d’entretien près de la place centrale. Le projet porte sur les espaces piétons et le mobilier urbain.\n\nLes riverains sont invités à rester attentifs aux informations du quartier. Cette annonce ne ferme pas les lieux du jeu et ne modifie pas les déplacements disponibles.';image_key:='transport';importance_value:=85;
WHEN 2 THEN kind:='culture';category_name:='Culture';headline:='Les associations culturelles donnent rendez-vous à '||ci.name;summary_text:='Une rencontre ouverte à la création fait vivre le centre culturel.';body_text:='Le centre culturel prépare une rencontre consacrée aux initiatives locales. Les membres de l’association présentent leurs projets, entre musique, arts visuels et échanges avec les habitants.\n\nL’organisation propose déjà des activités collectives à ses membres. Les modalités de participation restent celles de la fiche de l’organisation et de votre agenda.';image_key:='culture';importance_value:=65;
WHEN 3 THEN kind:='recrutement';category_name:='Emploi';headline:='Les employeurs de '||ci.name||' mettent leurs offres en lumière';summary_text:='Les métiers administratifs et techniques sont au cœur d’un rendez-vous professionnel.';body_text:='Les employeurs locaux présentent leurs métiers et les compétences recherchées. Les jeunes actifs et les personnes en début de carrière peuvent retrouver les offres accessibles dans leur ville.\n\nUne candidature reste soumise aux conditions habituelles du jeu. Cet article ne garantit ni embauche ni salaire et n’ajoute pas d’offre fictive à la page Vie.';importance_value:=70;
WHEN 4 THEN kind:='sport';category_name:='Sport';headline:='Une rencontre sportive anime '||ci.name;summary_text:='Le collectif sportif local prépare un rendez-vous pour ses membres.';body_text:='Le collectif sportif met à l’honneur la pratique amateur et les rencontres entre habitants. Le rendez-vous s’inscrit dans les activités déjà proposées par l’association.\n\nLes membres peuvent consulter la fiche de l’organisation pour les prochaines participations. Les horaires, l’énergie et les récompenses restent validés par les règles existantes.';importance_value:=60;
WHEN 5 THEN kind:='transport';category_name:='Transport';headline:='À '||ci.name||', les transports font le point sur les déplacements';summary_text:='Une information locale accompagne les voyageurs et les trajets du quotidien.';body_text:='Les services de transport diffusent une information sur l’organisation des déplacements dans la ville. Les habitants sont invités à consulter les points de départ et les lieux déjà accessibles.\n\nLe transport public du jeu conserve son coût et sa durée habituels. Cette information n’ajoute ni perturbation effective ni fermeture de station.';image_key:='transport';importance_value:=85;
ELSE kind:='universite';category_name:='Éducation';headline:='La vie universitaire s’organise à '||ci.name;summary_text:='Les étudiants retrouvent les filières et les rendez-vous de leur campus.';body_text:='Le campus présente les filières et les initiatives étudiantes accessibles dans la ville. Les associations rappellent le rôle des rencontres dans la vie universitaire.\n\nLes inscriptions, les cours et la progression restent gérés dans la page Vie. L’article informe les étudiants sans modifier leurs résultats ni leur agenda.';importance_value:=70;
END CASE;
SELECT id INTO lid FROM public.locations WHERE city_id=ci.id AND district_id IS NOT NULL AND accessible AND kind=CASE slot WHEN 0 THEN 'commerce' WHEN 1 THEN 'mairie' WHEN 2 THEN 'culture' WHEN 3 THEN 'entreprise' WHEN 4 THEN 'sport' WHEN 5 THEN 'transport' ELSE 'universite' END ORDER BY name LIMIT 1;
IF lid IS NULL THEN SELECT id INTO lid FROM public.locations WHERE city_id=ci.id AND district_id IS NOT NULL AND accessible ORDER BY name LIMIT 1; END IF;
IF slot IN(2,4,6) THEN SELECT o.id,o.location_id INTO oid,lid FROM public.organizations o WHERE city_id=ci.id AND kind=CASE slot WHEN 2 THEN 'culture' WHEN 4 THEN 'sport' ELSE 'student' END AND status='active' ORDER BY name LIMIT 1; SELECT id INTO oeid FROM public.organization_events WHERE organization_id=oid AND status='active' ORDER BY title LIMIT 1; END IF;
INSERT INTO public.events(title,description,city_id,starts_at,scope,region,category,importance,location_id,organization_id,organization_event_id,source_id,event_key,news_title,news_summary,news_body,image,target_kind)
VALUES(headline,summary_text,ci.id,published_time,'local',ci.region,category_name,importance_value,lid,oid,oeid,CASE WHEN ci.id='lyon' THEN 'journal-lyon' WHEN ci.id='lille' THEN 'tribune-nord' ELSE 'civitas-matin' END,'daily:'||ci.id||':'||(day-i),headline,summary_text,replace(body_text,'\n',E'\n'),image_key,CASE WHEN oid IS NOT NULL THEN 'organization' ELSE 'city' END) ON CONFLICT(event_key) DO NOTHING;
GET DIAGNOSTICS slot=ROW_COUNT;result_count:=result_count+slot;
END LOOP;
INSERT INTO public.events(title,description,starts_at,scope,category,importance,source_id,event_key,news_body,target_kind)
VALUES('CIVITAS : les initiatives locales à l’honneur','Culture, emploi et environnement nourrissent les projets des villes.',published_time,'national',CASE extract(doy FROM day-i)::integer%4 WHEN 0 THEN 'Société' WHEN 1 THEN 'Technologie' WHEN 2 THEN 'Environnement' ELSE 'Économie' END,75,'france-direct','national:'||(day-i),'Dans les villes de CIVITAS, les initiatives des habitants font émerger de nouvelles rencontres. Les associations, les campus et les employeurs rythment la vie quotidienne. Chaque ville garde sa personnalité tout en participant à cette histoire commune.','general') ON CONFLICT(event_key) DO NOTHING;
INSERT INTO public.events(title,description,starts_at,scope,region,category,importance,source_id,event_key,news_body,target_kind)
SELECT 'Les initiatives de '||region,'La région fait le point sur sa vie culturelle et associative.',published_time,'regional',region,'Culture',50,'observateur','regional:'||region||':'||(day-i),'Les projets culturels et associatifs se poursuivent dans la région. Les villes partagent des idées autour de la vie locale, des rencontres et des lieux publics. Consultez les organisations de votre ville pour découvrir les rendez-vous déjà accessibles.','general' FROM public.cities GROUP BY region ON CONFLICT(event_key) DO NOTHING;
END LOOP;
FOR lid IN SELECT id FROM public.events WHERE status='scheduled' AND starts_at<=public.game_now() AND source_id IS NOT NULL ORDER BY starts_at LIMIT 100 LOOP PERFORM public.publish_world_event(lid); END LOOP;
RETURN result_count;
END $$;
REVOKE ALL ON FUNCTION public.refresh_world_news() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.refresh_world_news() TO service_role;